{"packet_id":"D071-01","doc_id":"D071","jurisdiction":"Newark, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Newark HOME-assisted unit maximum rent limits","requirement":"Rents for HOME-assisted units may not exceed the maximum HOME rent limits (the lesser of the area fair market rent or 30% of the adjusted income of a family at 65% of area median income), and the owner must give tenants at least 30 days' written notice before any rent increase.","key_value":"lesser of FMR or 30% of adjusted income of a family at 65% of area median income","coverage_conditions":"Units assisted with HOME Program funds (HOME-assisted units) in the City of Newark.","applicability":{"conditions":[{"type":"other","text":"only HOME-assisted units receiving HOME Program funds are covered"}],"per_tenancy":null,"coverage_quotes":["The DHA must review and approve rents proposed by the owner for units subject to the maximum rent limitations"]},"exemptions":"Rents for a project need not be lower than the HOME rent limits in effect at the time of project commitment.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Newark, N.J., Code § 2:10-1.2","quoted_span":"(i) The fair market rent for existing housing for comparable units in the area as established by HUD under 24 CFR 888.111; or (ii) A rent that does not exceed 30% of the adjusted income of a family whose annual income equals 65% of the median income for the area, as determined by HUD, with adjustments for number of bedrooms in the unit.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D071-01","doc_id":"D071","jurisdiction":"Newark, NJ","category":"screening_restrictions","lifecycle":"enacted","title":"Newark HOME voucher-holder nondiscrimination","requirement":"An owner of HOME-assisted units may not refuse to lease to a Section 8 certificate or voucher holder, or the holder of a comparable HOME tenant-based rental assistance document, because of that status.","key_value":null,"coverage_conditions":"HOME-assisted units in the City of Newark.","applicability":{"conditions":[{"type":"other","text":"only HOME-assisted units receiving HOME Program funds are covered"}],"per_tenancy":null,"coverage_quotes":["The owner cannot refuse to lease HOME-assisted units to a certificate or voucher holder under 24 CFR part 982"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Newark, N.J., Code § 2:10-1.2","quoted_span":"The owner cannot refuse to lease HOME-assisted units to a certificate or voucher holder under 24 CFR part 982-Section 8 Tenant-Based Assistance","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
